  var FOUL_REASONS = ["\u6218\u672F\u72AF\u89C4", "\u80CC\u540E\u94F2\u7403", "\u62FC\u62A2\u52A8\u4F5C\u8FC7\u5927", "\u62C9\u62FD\u7403\u8863"];
