      drawText(ctx2, "\u70B9\u51FB\u4EFB\u610F\u6D41\u6D3E\u5361\u7247\uFF0C\u81EA\u52A8\u586B\u5165\u53F3\u4FA7\u5408\u6210\u5668\u5E76\u5173\u95ED\u672C\u9875", mx + 28, my + 58, { size: 12.5, color: "#7DD3FC" });
