        const roleAssetId = p.role === "GK" ? "role_gk" : ["CB", "LB", "RB", "LWB", "RWB"].includes(p.role) ? "role_def" : ["CDM", "CM", "CAM", "LM", "RM"].includes(p.role) ? "role_mid" : "role_att";
        const roleImg = AssetLoader.get(roleAssetId);
