        drawRoundRect(ctx2, sx - 38, sy - 26, 76, 52, 7, isSel ? "#1E3A5F" : "rgba(14, 22, 40, 0.92)", isSel ? "#38BDF8" : p.customOffset ? "#38BDF8" : THEME.GOLD, isSel ? 2 : 1);
