      drawText(ctx2, `\u4E34\u573A\u6362\u4EBA (\u5DF2\u7528 ${subsUsed}/5 \u540D\u989D)`, 900, 102, { size: 13, bold: true, color: THEME.GOLD_LIGHT });
      drawText(ctx2, "1. \u70B9\u9009\u4F53\u80FD\u4E0D\u8DB3\u7684\u573A\u4E0A\u7403\u5458\u6362\u4E0B", 900, 122, { size: 10, color: THEME.TX2 });
