      drawText(ctx2, "\u5F53\u524D 2D \u6BD4\u8D5B\u5F15\u64CE\u5B9E\u65F6\u884C\u4E3A\u4FEE\u6B63", mx + 46, my + 100, { size: 14, bold: true, color: "#38BDF8" });
